// GoogleAutocompleteScriptLoader.ts

import { getScriptLoader, type ScriptLoader } from '@bigcommerce/script-loader';
import { type GoogleMapsSdk } from './googleAutocompleteTypes';

export default class GoogleAutocompleteScriptLoader {
    private _scriptLoader: ScriptLoader;
    // La promise ora si risolverà con l'oggetto `google.maps` di base.
    private _googleMapsPromise?: Promise<GoogleMapsSdk>;

    constructor() {
        this._scriptLoader = getScriptLoader();
    }

    loadMapsSdk(apiKey: string): Promise<GoogleMapsSdk> {
        if (this._googleMapsPromise) {
            return this._googleMapsPromise;
        }

        // Usiamo una URL più pulita. La libreria 'places' verrà caricata dinamicamente dopo.
        const params = [`key=${apiKey}`, 'loading=async'].join('&');
        const scriptUrl = `https://maps.googleapis.com/maps/api/js?${params}`;

        // La libreria @bigcommerce/script-loader dovrebbe supportare il caricamento asincrono.
        // Se così non fosse, il concetto rimane lo stesso: caricare lo script senza bloccare la pagina.
        this._googleMapsPromise = this._scriptLoader.loadScript(scriptUrl).then(() => {
            if (window.google && window.google.maps) {
                return window.google.maps;
            }

            throw new Error('Failed to load Google Maps SDK.');
        });

        return this._googleMapsPromise;
    }
}