// GoogleAutocompleteService.ts (VERSIONE CORRETTA CHE ACCETTA I FILTRI)

import getGoogleAutocompleteScriptLoader from './getGoogleAutocompleteScriptLoader';
import type GoogleAutocompleteScriptLoader from './GoogleAutocompleteScriptLoader';

/**
 * Esportiamo il tipo AutocompleteSuggestion per poterlo utilizzare
 * facilmente nei componenti React (ad esempio, per lo stato).
 */
export type AutocompleteSuggestion = google.maps.places.AutocompleteSuggestion;

/**
 * Definiamo un'interfaccia per le opzioni che possiamo passare al nostro metodo.
 */
interface FetchSuggestionsOptions {
    types?: string[];
    componentRestrictions?: google.maps.places.ComponentRestrictions;
}

/**
 * Questa classe è stata aggiornata per utilizzare le API moderne di Google Maps Places.
 */
export default class GoogleAutocompleteService {
    private _scriptLoader: GoogleAutocompleteScriptLoader;
    private _placesLibraryPromise?: Promise<google.maps.PlacesLibrary>;
    private _placesPromise?: Promise<google.maps.places.PlacesService>;

    constructor(
        private _apiKey: string,
        scriptLoader: GoogleAutocompleteScriptLoader = getGoogleAutocompleteScriptLoader(),
    ) {
        this._scriptLoader = scriptLoader;
    }

    private _loadPlacesLibrary(): Promise<google.maps.PlacesLibrary> {
        if (!this._placesLibraryPromise) {
            this._placesLibraryPromise = this._scriptLoader
                .loadMapsSdk(this._apiKey)
                .then(googleMapsSdk => {
                    return googleMapsSdk.importLibrary('places') as Promise<google.maps.PlacesLibrary>;
                });
        }
        
        return this._placesLibraryPromise;
    }

    /**
     * *** CORREZIONE CHIAVE ***
     * La funzione ora accetta un secondo argomento opzionale `options`
     * per gestire i filtri.
     */
    public async fetchSuggestions(
        input: string,
        options: FetchSuggestionsOptions = {},
    ): Promise<AutocompleteSuggestion[]> {
        if (!input) {
            return [];
        }

        try {
            const placesLibrary = await this._loadPlacesLibrary();
            const { AutocompleteSuggestion } = placesLibrary;

            const request: google.maps.places.AutocompleteRequest = {
                input,
            };

            // Mappiamo le opzioni passate ai parametri della richiesta API di Google.
            // La nuova API usa `includedPrimaryTypes` per i tipi.
            if (options.types) {
                request.includedPrimaryTypes = options.types;
            }

            // La nuova API usa `includedRegionCodes` per il paese.
            if (options.componentRestrictions?.country) {
                const { country } = options.componentRestrictions;
                request.includedRegionCodes = Array.isArray(country) ? country : [country];
            }
            
            const response = await AutocompleteSuggestion.fetchAutocompleteSuggestions(request);
            
            return response.suggestions;

        } catch (error) {
            console.error('Errore durante il recupero dei suggerimenti di autocompletamento:', error);
            return [];
        }
    }

    public getPlacesServices(): Promise<google.maps.places.PlacesService> {
        const node = document.createElement('div');

        if (!this._placesPromise) {
            this._placesPromise = this._scriptLoader
                .loadMapsSdk(this._apiKey)
                .then((googleMapsSdk) => {
                    if (!googleMapsSdk.places.PlacesService) {
                        throw new Error('`PlacesService` is undefined');
                    }

                    return new googleMapsSdk.places.PlacesService(node);
                });
        }

        return this._placesPromise;
    }
}